corrected_code:
import { verifyUser } from "./auth";

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const match = url.pathname.match(/^\/api\/chat-rooms\/([^\/]+)\/history$/);

    if (request.method === "GET" && match) {
      const roomId = match[1];
      const user = await verifyUser(request.headers.get("Authorization"));
      if (!user) return new Response("Unauthorized", { status: 401 });

      // Verify user is an active participant of the chat room in KV or D1
      const isMember = await env.CHAT_MEMBERS_KV.get(`room:${roomId}:user:${user.id}`);
      if (!isMember) {
        return new Response("Forbidden: Not a member of this chat room", { status: 403 });
      }

      const id = env.CHAT_ROOM.idFromName(roomId);
      const stub = env.CHAT_ROOM.get(id);

      return stub.fetch(request);
    }

    return new Response("Not Found", { status: 404 });
  }
};

export class ChatRoomDO {
  constructor(state, env) {
    this.state = state;
  }

  async fetch(request) {
    const messages = (await this.state.storage.get("messages")) || [];
    return new Response(JSON.stringify({ messages }), {
      headers: { "Content-Type": "application/json" }
    });
  }
}
